mapper.select:
SELECT DATE_FORMAT(e.create_time, '%Y-%m-%d') AS statDate, COUNT(1) AS addTimes, CAST(COALESCE(SUM(e.quantity), 0) AS SIGNED) AS addQuantity, COUNT(DISTINCT e.user_id) AS addUsers, COUNT(DISTINCT e.product_id) AS addProducts FROM ck_shop_cart_event e WHERE e.del_flag = 0
AND e.create_time >= #{start} AND e.create_time <= #{end}
GROUP BY DATE_FORMAT(e.create_time, '%Y-%m-%d') ORDER BY statDate ASC

SELECT e.product_id AS productId, e.sku_id AS skuId, COALESCE(t.title, tz.title, p.spu_code) AS title, p.spu_code AS spuCode, p.main_image AS coverUrl, p.status AS productStatus, c.combination_name AS skuName, COUNT(1) AS addTimes, CAST(COALESCE(SUM(e.quantity), 0) AS SIGNED) AS addQuantity, COUNT(DISTINCT e.user_id) AS addUsers, MAX(e.create_time) AS lastAddTime FROM ck_shop_cart_event e LEFT JOIN ck_shop_product p ON p.id = e.product_id LEFT JOIN ck_shop_product_translation t ON t.product_id = e.product_id AND t.language_code = #{lang} LEFT JOIN ck_shop_product_translation tz ON tz.product_id = e.product_id AND tz.language_code = #{defaultLang} LEFT JOIN ck_shop_product_sku_combination c ON c.id = e.sku_id AND e.sku_id <> '' WHERE e.del_flag = 0
AND e.create_time >= #{start} AND e.create_time <= #{end}
AND (t.title LIKE CONCAT('%', #{keyword}, '%') OR tz.title LIKE CONCAT('%', #{keyword}, '%') OR p.spu_code LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY e.product_id, e.sku_id, COALESCE(t.title, tz.title, p.spu_code), p.spu_code, p.main_image, p.status, c.combination_name ORDER BY addTimes DESC, addQuantity DESC, MAX(e.create_time) DESC LIMIT #{limit}

SELECT e.id AS id, e.username AS username, s.name AS storeName, e.product_id AS productId, COALESCE(t.title, tz.title, p.spu_code) AS title, p.spu_code AS spuCode, e.sku_id AS skuId, c.combination_name AS skuName, e.quantity AS quantity, e.event_type AS eventType, e.source AS source, e.create_time AS createTime FROM ck_shop_cart_event e LEFT JOIN ck_shop_store s ON s.id = e.store_id LEFT JOIN ck_shop_product p ON p.id = e.product_id LEFT JOIN ck_shop_product_translation t ON t.product_id = e.product_id AND t.language_code = #{lang} LEFT JOIN ck_shop_product_translation tz ON tz.product_id = e.product_id AND tz.language_code = #{defaultLang} LEFT JOIN ck_shop_product_sku_combination c ON c.id = e.sku_id AND e.sku_id <> '' WHERE e.del_flag = 0 AND e.create_time >= #{start} AND e.create_time <= #{end}
AND (t.title LIKE CONCAT('%', #{keyword}, '%') OR tz.title LIKE CONCAT('%', #{keyword}, '%') OR p.spu_code LIKE CONCAT('%', #{keyword}, '%') OR e.username LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY e.create_time DESC, e.id DESC
